      messageIds.add(msg.id);
      appendMessage(msg);
      messageInput.value = '';
    } else {
      const error = await response.json();
      console.error('Failed to send message:', error.error);
    }
  } catch (err) {
    console.error('Failed to send message:', err);
  }
});

// Initialize
loadMessages();
connectStream();
